diff --git a/frontend/src/lib/audio/duration.test.ts b/frontend/src/lib/audio/duration.test.ts
new file mode 100644
index 0000000..31e757c
--- /dev/null
+++ b/frontend/src/lib/audio/duration.test.ts
@@ -0,0 +1,163 @@
+/**
+ * Testes do `measureAudioDuration()` — incidentes #203/#204 (31/08, Jussara).
+ *
+ * Rodar (Node ≥ 22.18, type-stripping nativo):
+ *   node --test src/lib/audio/duration.test.ts
+ *
+ * O DEFEITO COBERTO: a duração era medida só pelo <audio> (metadados) e, se
+ * ele não respondesse, pelo decode do arquivo INTEIRO em PCM. Áudio gravado
+ * no iPhone reprova nos dois: o Safari do iOS ignora `preload="metadata"` e
+ * não carrega mídia sem gesto do usuário, e decodificar 30min de m4a estoura
+ * a RAM do celular. A duração voltava `null`, a linha do arquivo ficava
+ * "medindo…" para sempre, o total ficava 00:00 e o botão "Treinar voz" nunca
+ * saía do disabled — a aluna descreveu exatamente isso ("fica medindo… e não
+ * aparece nenhum outro comando", "eu clico e o botão não muda de cor").
+ *
+ * Agora a duração sai do cabeçalho do container antes de qualquer decoder:
+ * `mvhd` do MP4/M4A e header do WAV, com `file.slice()` de alguns KB.
+ *
+ * O caso 1 é a forma do arquivo do iPhone: `moov` DEPOIS do `mdat` (o MP4 do
+ * celular não é otimizado pra streaming), que é justamente o que quebra quem
+ * só olha o começo do arquivo.
+ */
+import { test, before } from "node:test";
+import assert from "node:assert/strict";
+
+let measureAudioDuration: (f: File) => Promise<number | null>;
+
+before(async () => {
+  // O módulo só mede no client. O <audio> mockado SEMPRE falha: garante que
+  // todo número que aparecer aqui veio do cabeçalho, não do navegador.
+  (globalThis as Record<string, unknown>).window = {};
+  (globalThis as Record<string, unknown>).document = {
+    createElement: () => ({
+      removeAttribute() {},
+      set src(_v: string) {
+        setTimeout(() => (this as { onerror?: () => void }).onerror?.(), 0);
+      },
+    }),
+  };
+  URL.createObjectURL = () => "blob:test";
+  URL.revokeObjectURL = () => {};
+  ({ measureAudioDuration } = await import("./duration.ts"));
+});
+
+function box(tag: string, payload: Buffer, size64 = false): Buffer {
+  if (size64) {
+    const h = Buffer.alloc(16);
+    h.writeUInt32BE(1, 0);
+    h.write(tag, 4, "latin1");
+    h.writeBigUInt64BE(BigInt(payload.length + 16), 8);
+    return Buffer.concat([h, payload]);
+  }
+  const h = Buffer.alloc(8);
+  h.writeUInt32BE(payload.length + 8, 0);
+  h.write(tag, 4, "latin1");
+  return Buffer.concat([h, payload]);
+}
+
+/** Payload de um `mvhd` versão 0 (duration/timescale em 32 bits). */
+function mvhdV0(timescale: number, duration: number): Buffer {
+  const p = Buffer.alloc(100);
+  p.writeUInt8(0, 0);
+  p.writeUInt32BE(timescale, 12);
+  p.writeUInt32BE(duration, 16);
+  return p;
+}
+
+/** Payload de um `mvhd` versão 1 (duration em 64 bits). */
+function mvhdV1(timescale: number, duration: number): Buffer {
+  const p = Buffer.alloc(112);
+  p.writeUInt8(1, 0);
+  p.writeUInt32BE(timescale, 20);
+  p.writeBigUInt64BE(BigInt(duration), 24);
+  return p;
+}
+
+function wav(byteRate: number, dataBytes: number): Buffer {
+  const fmt = Buffer.alloc(16);
+  fmt.writeUInt16LE(1, 0);
+  fmt.writeUInt16LE(1, 2);
+  fmt.writeUInt32LE(44100, 4);
+  fmt.writeUInt32LE(byteRate, 8);
+  fmt.writeUInt16LE(2, 12);
+  fmt.writeUInt16LE(16, 14);
+  const chunk = (tag: string, payload: Buffer) => {
+    const h = Buffer.alloc(8);
+    h.write(tag, 0, "latin1");
+    h.writeUInt32LE(payload.length, 4);
+    return Buffer.concat([h, payload]);
+  };
+  const body = Buffer.concat([
+    Buffer.from("WAVE", "latin1"),
+    chunk("fmt ", fmt),
+    chunk("data", Buffer.alloc(dataBytes)),
+  ]);
+  const h = Buffer.alloc(8);
+  h.write("RIFF", 0, "latin1");
+  h.writeUInt32LE(body.length, 4);
+  return Buffer.concat([h, body]);
+}
+
+// : o Buffer do Node não serve como BlobPart tipado.
+const arquivo = (buf: Buffer, nome: string) => new File([new Uint8Array(buf)], nome);
+
+test("m4a do iPhone: `moov` depois do `mdat`, 30min", async () => {
+  const f = arquivo(
+    Buffer.concat([
+      box("ftyp", Buffer.from("M4A mp42isom", "latin1")),
+      box("mdat", Buffer.alloc(3_000_000)),
+      box("moov", Buffer.concat([box("mvhd", mvhdV0(44100, 44100 * 1800)), box("trak", Buffer.alloc(50))])),
+    ]),
+    "gravacao.m4a",
+  );
+  assert.equal(await measureAudioDuration(f), 1800);
+});
+
+test("mp4 com `moov` no começo e `mvhd` versão 1 (duração 64 bits)", async () => {
+  const f = arquivo(
+    Buffer.concat([
+      box("ftyp", Buffer.from("isom", "latin1")),
+      box("moov", box("mvhd", mvhdV1(1000, 125_500))),
+      box("mdat", Buffer.alloc(1000)),
+    ]),
+    "a.mp4",
+  );
+  assert.equal(await measureAudioDuration(f), 125.5);
+});
+
+test("mp4 com `mdat` de tamanho 64 bits é pulado sem ser lido", async () => {
+  const f = arquivo(
+    Buffer.concat([
+      box("ftyp", Buffer.from("isom", "latin1")),
+      box("mdat", Buffer.alloc(100), true),
+      box("moov", box("mvhd", mvhdV0(600, 600 * 90))),
+    ]),
+    "b.m4a",
+  );
+  assert.equal(await measureAudioDuration(f), 90);
+});
+
+test("wav pelo byte rate do `fmt `", async () => {
+  assert.equal(await measureAudioDuration(arquivo(wav(176_400, 176_400 * 30), "g.wav")), 30);
+});
+
+test("formato sem cabeçalho conhecido cai fora e devolve null", async () => {
+  const f = arquivo(Buffer.concat([Buffer.from("ID3", "latin1"), Buffer.alloc(500)]), "x.mp3");
+  assert.equal(await measureAudioDuration(f), null);
+});
+
+test("mp4 truncado (box mentindo o tamanho) não trava nem inventa duração", async () => {
+  const f = arquivo(
+    Buffer.concat([
+      box("ftyp", Buffer.from("isom", "latin1")),
+      Buffer.from([0, 0, 255, 255, 0x6d, 0x6f, 0x6f, 0x76]),
+    ]),
+    "t.m4a",
+  );
+  assert.equal(await measureAudioDuration(f), null);
+});
+
+test("arquivo vazio devolve null", async () => {
+  assert.equal(await measureAudioDuration(arquivo(Buffer.alloc(0), "v.m4a")), null);
+});
diff --git a/frontend/src/lib/audio/duration.ts b/frontend/src/lib/audio/duration.ts
index cecc84b..a9c1a9e 100644
--- a/frontend/src/lib/audio/duration.ts
+++ b/frontend/src/lib/audio/duration.ts
@@ -8,11 +8,27 @@
  * m4a) e falhava/travava → total 00:00 e botão Treinar nunca habilitava.
  * O decode completo fica só de fallback (webm/opus do MediaRecorder não
  * informa duração no cabeçalho e reporta Infinity no <audio>).
+ *
+ * ANTES DO <audio>, agora, o cabeçalho do container (caso Jussara 31/08,
+ * incidentes #203/#204): o Safari do iOS ignora `preload="metadata"` e não
+ * carrega mídia sem gesto do usuário, então `loadedmetadata` nunca dispara
+ * pro áudio que a pessoa acabou de gravar no iPhone — a medição caía no
+ * timeout de 8s e depois no decode do arquivo inteiro, que estoura no
+ * celular. Resultado: duração null pra sempre, "medindo…" eterno na linha,
+ * total 00:00 e botão Treinar morto. Ler o `mvhd` do MP4/M4A (e o header do
+ * WAV) resolve isso com alguns KB de `file.slice()`, sem tocar no decoder do
+ * navegador e sem depender de codec instalado.
  */

+/** Quanto de um arquivo aceitamos varrer procurando o `moov` (bytes). */
+const MP4_SCAN_LIMIT = 512 * 1024 * 1024;
+
 export async function measureAudioDuration(file: File): Promise<number | null> {
   if (typeof window === "undefined") return null;

+  const viaHeader = await headerDuration(file);
+  if (viaHeader != null) return viaHeader;
+
   const viaMetadata = await metadataDuration(file);
   if (viaMetadata != null) return viaMetadata;

@@ -40,6 +56,143 @@ export async function measureAudioDuration(file: File): Promise<number | null> {
   }
 }

+/**
+ * Duração lida direto do cabeçalho do container, sem decodificar nada.
+ * Cobre os dois formatos que os alunos mais mandam de celular e de gravador:
+ * MP4/M4A (iPhone) e WAV. Qualquer outro formato — ou qualquer arquivo
+ * malformado — devolve null e a medição segue pros caminhos antigos.
+ */
+async function headerDuration(file: File): Promise<number | null> {
+  try {
+    const head = new DataView(await file.slice(0, 16).arrayBuffer());
+    if (head.byteLength < 12) return null;
+
+    if (lerTag(head, 0) === "RIFF" && lerTag(head, 8) === "WAVE") {
+      return await wavDuration(file);
+    }
+    // MP4/M4A: o primeiro box costuma ser `ftyp`. Alguns arquivos vêm com um
+    // `skip`/`free` antes — o walker abaixo lida com isso, aqui só peneiramos.
+    const primeiroBox = lerTag(head, 4);
+    if (primeiroBox === "ftyp" || primeiroBox === "moov" || primeiroBox === "free") {
+      return await mp4Duration(file);
+    }
+    return null;
+  } catch {
+    return null;
+  }
+}
+
+function lerTag(view: DataView, offset: number): string {
+  let s = "";
+  for (let i = 0; i < 4; i++) s += String.fromCharCode(view.getUint8(offset + i));
+  return s;
+}
+
+/**
+ * Caminha os boxes de nível superior do MP4 até achar `moov`, desce até
+ * `mvhd` e lê duration/timescale. Nunca lê o `mdat`: pula pelo tamanho
+ * declarado, então um arquivo de 400MB custa alguns KB de leitura.
+ *
+ * O `moov` do iPhone costuma ficar NO FIM do arquivo (não é MP4 otimizado
+ * pra streaming) — por isso o walker vai até o fim em vez de olhar só o
+ * começo.
+ */
+async function mp4Duration(file: File): Promise<number | null> {
+  const moov = await acharBox(file, 0, Math.min(file.size, MP4_SCAN_LIMIT), "moov");
+  if (!moov) return null;
+  const mvhd = await acharBox(file, moov.conteudo, moov.fim, "mvhd");
+  if (!mvhd) return null;
+
+  const tamanho = Math.min(mvhd.fim - mvhd.conteudo, 128);
+  if (tamanho < 20) return null;
+  const view = new DataView(
+    await file.slice(mvhd.conteudo, mvhd.conteudo + tamanho).arrayBuffer(),
+  );
+
+  const versao = view.getUint8(0);
+  let timescale: number;
+  let duracao: number;
+  if (versao === 1) {
+    if (view.byteLength < 32) return null;
+    timescale = view.getUint32(20);
+    // duration de 64 bits: o high word só passaria de 0 com séculos de áudio.
+    duracao = Number(view.getBigUint64(24));
+  } else {
+    timescale = view.getUint32(12);
+    duracao = view.getUint32(16);
+  }
+
+  if (!timescale || !Number.isFinite(duracao) || duracao <= 0) return null;
+  const segundos = duracao / timescale;
+  return Number.isFinite(segundos) && segundos > 0 ? segundos : null;
+}
+
+type Box = { conteudo: number; fim: number };
+
+/** Procura um box pelo nome varrendo a lista de boxes de [inicio, limite). */
+async function acharBox(
+  file: File,
+  inicio: number,
